begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('cccc0000-0000-4000-8000-000000000001','season-organizer@test.invalid','{"display_name":"Season Organizer"}'),
 ('cccc0000-0000-4000-8000-000000000002','season-judge@test.invalid','{"display_name":"Season Judge"}');
insert into public.staff_accounts(id,email,display_name) select id,email,'Season Fixture' from auth.users where id in('cccc0000-0000-4000-8000-000000000001','cccc0000-0000-4000-8000-000000000002');
insert into public.staff_roles values('cccc0000-0000-4000-8000-000000000001','organizer'),('cccc0000-0000-4000-8000-000000000002','main_judge');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cccc0000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.save_season('dddd0000-0000-4000-8000-000000000001','League 2026',2026,'2026-01-01','2026-12-31')$$,'organizer creates season');
select is((select status::text from public.seasons where id='dddd0000-0000-4000-8000-000000000001'),'draft','season starts draft');
select lives_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000001','dddd0000-0000-4000-8000-000000000001','First Tour',1,'2026-03-01','2026-03-03')$$,'organizer creates ordered tour');
select throws_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000002','dddd0000-0000-4000-8000-000000000001','Duplicate',1,'2026-05-01','2026-05-03')$$,'23505',null,'duplicate tour order rejected');
select throws_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000002','dddd0000-0000-4000-8000-000000000001','Outside Season',2,'2027-05-01','2027-05-03')$$,'22023','Invalid tour details','tour dates must fit season');
select throws_ok($$select public.save_season('dddd0000-0000-4000-8000-000000000001','Shrink Season',2026,'2026-04-01','2026-12-31')$$,'22023','Dates exclude an existing tour','season cannot exclude an existing tour');
select throws_ok($$select public.save_season(gen_random_uuid(),'Bad Dates',2026,'2026-12-31','2026-01-01')$$,'22023','Invalid season details','reversed season dates rejected');
select lives_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000001','dddd0000-0000-4000-8000-000000000001','Edited Tour',3,'2026-03-01','2026-03-03')$$,'draft tour editable');
select lives_ok($$select public.save_season('dddd0000-0000-4000-8000-000000000001','Edited Season',2026,'2026-01-01','2026-12-31')$$,'draft season editable');
select is((select before_state->>'name' from public.audit_logs where action='season.updated' and entity_id='dddd0000-0000-4000-8000-000000000001'),'League 2026','season audit preserves before state');
select is((select after_state->>'name' from public.audit_logs where action='tour.updated' and entity_id='eeee0000-0000-4000-8000-000000000001'),'Edited Tour','tour audit preserves after state');
select throws_ok($$select public.start_season('dddd0000-0000-4000-8000-000000000001')$$,'22023','Stage and settings readiness required','cannot start incomplete season');
select lives_ok($$select public.save_season('dddd0000-0000-4000-8000-000000000002','Second Season',2027,'2027-01-01','2027-12-31')$$,'second season created');
select throws_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000001','dddd0000-0000-4000-8000-000000000002','Moved Tour',1,'2027-03-01','2027-03-03')$$,'22023','Tour belongs to another season','tour cannot move parent');
select throws_ok($$insert into public.seasons(id,name,year,starts_on,ends_on) values(gen_random_uuid(),'Bypass',2026,'2026-01-01','2026-12-31')$$,'42501',null,'direct season insertion denied');
select throws_ok($$update public.tours set name='Bypass'$$,'42501',null,'direct tour update denied');
select throws_ok($$delete from public.seasons$$,'42501',null,'season deletion denied');
-- Simulate a started legacy/future-ready season using trusted fixture SQL.
reset role;
update public.seasons set status='started',started_at=now() where id='dddd0000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.save_season('dddd0000-0000-4000-8000-000000000001','Locked Edit',2026,'2026-01-01','2026-12-31')$$,'22023','Season configuration locked','started season immutable');
select throws_ok($$select public.save_tour('eeee0000-0000-4000-8000-000000000001','dddd0000-0000-4000-8000-000000000001','Locked Edit',3,'2026-03-01','2026-03-03')$$,'22023','Season configuration locked','started season tour immutable');
select is(public.age_group_for_birth_year(2014,2026),'U13','age 12 U13');
select is(public.age_group_for_birth_year(2013,2026),'U15','age 13 U15');
select is(public.age_group_for_birth_year(2012,2026),'U15','age 14 U15');
select is(public.age_group_for_birth_year(2011,2026),'U17','age 15 U17');
select is(public.age_group_for_birth_year(2010,2026),'U17','age 16 U17');
select is(public.age_group_for_birth_year(2009,2026),null,'age 17 ineligible');
select is(public.age_group_for_birth_year(2027,2026),null,'future birth year ineligible');
select is(public.age_group_for_birth_year(null,2026),null,'missing year ineligible');
select set_config('request.jwt.claims','{"sub":"cccc0000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.seasons where id in('dddd0000-0000-4000-8000-000000000001','dddd0000-0000-4000-8000-000000000002')),2,'active staff can read configuration');
select throws_ok($$select public.save_season(gen_random_uuid(),'Judge Season',2026,'2026-01-01','2026-12-31')$$,'42501','Organizer required','main judge cannot create season');
select throws_ok($$select public.save_tour(gen_random_uuid(),'dddd0000-0000-4000-8000-000000000002','Judge Tour',2,'2027-03-01','2027-03-03')$$,'42501','Organizer required','main judge cannot configure tour');
select throws_ok($$select public.start_season('dddd0000-0000-4000-8000-000000000002')$$,'42501','Organizer required','main judge cannot start season');
reset role;
update public.staff_accounts set active=false where id='cccc0000-0000-4000-8000-000000000002';
set local role authenticated;
select is((select count(*)::int from public.seasons),0,'inactive token cannot read seasons');
select is((select count(*)::int from public.tours),0,'inactive token cannot read tours');
set local role anon;
select throws_ok($$select * from public.seasons$$,'42501',null,'anonymous draft seasons denied');
select throws_ok($$select * from public.tours$$,'42501',null,'anonymous draft tours denied');
select throws_ok($$select public.save_season(gen_random_uuid(),'Anon Season',2026,'2026-01-01','2026-12-31')$$,'42501',null,'anonymous season mutation denied');
select * from finish();
rollback;
